"use strict";(globalThis.webpackChunkmy_website=globalThis.webpackChunkmy_website||[]).push([[849],{86164(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/docs/intro","label":"Willkommen im Benutzerhandbuch","docId":"intro","unlisted":false},{"type":"link","href":"/docs/systemanforderungen","label":"Systemanforderungen","docId":"systemanforderungen","unlisted":false},{"type":"category","label":"Planora","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/planora/start","label":"Planora \u2013 \xdcbersicht","docId":"planora/start","unlisted":false},{"type":"link","href":"/docs/planora/dashboard","label":"Dashboard","docId":"planora/dashboard","unlisted":false},{"type":"link","href":"/docs/planora/aufgaben","label":"Aufgaben","docId":"planora/aufgaben","unlisted":false},{"type":"link","href":"/docs/planora/projekte","label":"Projekte","docId":"planora/projekte","unlisted":false},{"type":"link","href":"/docs/planora/kalender","label":"Kalender","docId":"planora/kalender","unlisted":false},{"type":"link","href":"/docs/planora/terminbuchung","label":"Kalenderfreigabe & Terminbuchung","docId":"planora/terminbuchung","unlisted":false},{"type":"link","href":"/docs/planora/notizen","label":"Notizzettel","docId":"planora/notizen","unlisted":false},{"type":"link","href":"/docs/planora/zeiterfassung","label":"Zeiterfassung","docId":"planora/zeiterfassung","unlisted":false},{"type":"link","href":"/docs/planora/schilder","label":"Schilder","docId":"planora/schilder","unlisted":false},{"type":"category","label":"IT-Dokumentation","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/planora/it/uebersicht","label":"IT-Dokumentation \u2013 \xdcbersicht","docId":"planora/it/uebersicht","unlisted":false},{"type":"link","href":"/docs/planora/it/geraete","label":"Ger\xe4te","docId":"planora/it/geraete","unlisted":false},{"type":"link","href":"/docs/planora/it/netz","label":"Netz & IP-Adressen","docId":"planora/it/netz","unlisted":false},{"type":"link","href":"/docs/planora/it/dienste","label":"Dienste & Vertr\xe4ge","docId":"planora/it/dienste","unlisted":false},{"type":"link","href":"/docs/planora/it/wartung","label":"Wartung & Logbuch","docId":"planora/it/wartung","unlisted":false},{"type":"link","href":"/docs/planora/it/zugaenge","label":"Zug\xe4nge & Gastzug\xe4nge","docId":"planora/it/zugaenge","unlisted":false},{"type":"link","href":"/docs/planora/it/datenschutz","label":"Datenschutz","docId":"planora/it/datenschutz","unlisted":false}],"href":"/docs/category/it-dokumentation"},{"type":"link","href":"/docs/planora/statistiken","label":"Statistiken","docId":"planora/statistiken","unlisted":false},{"type":"link","href":"/docs/planora/einstellungen","label":"Einstellungen","docId":"planora/einstellungen","unlisted":false},{"type":"link","href":"/docs/planora/administration","label":"Administration","docId":"planora/administration","unlisted":false},{"type":"link","href":"/docs/planora/faq","label":"FAQ \u2013 H\xe4ufige Fragen","docId":"planora/faq","unlisted":false},{"type":"link","href":"/docs/planora/server","label":"Serververwaltung","docId":"planora/server","unlisted":true}],"href":"/docs/category/planora"},{"type":"category","label":"Scholar","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/scholar/start","label":"Scholar \u2013 \xdcbersicht","docId":"scholar/start","unlisted":false},{"type":"link","href":"/docs/scholar/dashboard","label":"Dashboard","docId":"scholar/dashboard","unlisted":false},{"type":"link","href":"/docs/scholar/schueler","label":"Sch\xfclerverwaltung","docId":"scholar/schueler","unlisted":false},{"type":"link","href":"/docs/scholar/eltern","label":"Elternverwaltung","docId":"scholar/eltern","unlisted":false},{"type":"link","href":"/docs/scholar/noten","label":"Noten & Zeugnisse","docId":"scholar/noten","unlisted":false},{"type":"link","href":"/docs/scholar/fachkonferenzen","label":"Fachkonferenzen (FKL-Verwaltung)","docId":"scholar/fachkonferenzen","unlisted":false},{"type":"link","href":"/docs/scholar/lernmittel","label":"Lernmittel","docId":"scholar/lernmittel","unlisted":false},{"type":"link","href":"/docs/scholar/ausgabe","label":"Lernmittelausgabe (Sch\xfclerhilfe)","docId":"scholar/ausgabe","unlisted":false},{"type":"link","href":"/docs/scholar/ags","label":"Arbeitsgemeinschaften (AGs)","docId":"scholar/ags","unlisted":false},{"type":"link","href":"/docs/scholar/geraete","label":"Ger\xe4teverwaltung","docId":"scholar/geraete","unlisted":false},{"type":"link","href":"/docs/scholar/bibliothek","label":"Bibliothek","docId":"scholar/bibliothek","unlisted":false},{"type":"link","href":"/docs/scholar/schliessacher","label":"Schlie\xdff\xe4cher","docId":"scholar/schliessacher","unlisted":false},{"type":"link","href":"/docs/scholar/wlan","label":"WLAN-Verwaltung","docId":"scholar/wlan","unlisted":false},{"type":"link","href":"/docs/scholar/finanzen","label":"Finanzen & Zahlungen","docId":"scholar/finanzen","unlisted":false},{"type":"link","href":"/docs/scholar/klassengeld","label":"Klassengeld","docId":"scholar/klassengeld","unlisted":false},{"type":"link","href":"/docs/scholar/schulkueche","label":"Schulk\xfcche","docId":"scholar/schulkueche","unlisted":false},{"type":"link","href":"/docs/scholar/checklisten","label":"Checklisten","docId":"scholar/checklisten","unlisted":false},{"type":"link","href":"/docs/scholar/listen","label":"Listen, Druck & \xdcbersichten","docId":"scholar/listen","unlisted":false},{"type":"link","href":"/docs/scholar/fallmanagement","label":"Fallmanagement & Kiosk","docId":"scholar/fallmanagement","unlisted":false},{"type":"link","href":"/docs/scholar/selbstservice","label":"Selbstservice-Portale","docId":"scholar/selbstservice","unlisted":false},{"type":"link","href":"/docs/scholar/mitarbeiter","label":"Mitarbeitende & On-/Offboarding","docId":"scholar/mitarbeiter","unlisted":false},{"type":"link","href":"/docs/scholar/administration","label":"Administration","docId":"scholar/administration","unlisted":false},{"type":"link","href":"/docs/scholar/faq","label":"FAQ \u2013 H\xe4ufige Fragen","docId":"scholar/faq","unlisted":false}],"href":"/docs/category/scholar"}]},"docs":{"intro":{"id":"intro","title":"Willkommen im Benutzerhandbuch","description":"Dieses Handbuch beschreibt den vollst\xe4ndigen Funktionsumfang der Schulverwaltungsanwendungen Scholar und Planora der Wilhelm-Raabe-Schule. Hier finden Sie detaillierte Erkl\xe4rungen zu allen Funktionen, Arbeitsabl\xe4ufen und Einstellungsm\xf6glichkeiten.","sidebar":"tutorialSidebar"},"planora/administration":{"id":"planora/administration","title":"Administration","description":"Administratorinnen und Administratoren verwalten in Planora Benutzerkonten und Rollen, richten Mailversand und Push ein, sichern die Datenbank und pflegen Lizenz sowie Updates. Die Bereiche erreichen Sie \xfcber Einstellungen; einzelne Punkte erscheinen nur mit Administratorrechten.","sidebar":"tutorialSidebar"},"planora/aufgaben":{"id":"planora/aufgaben","title":"Aufgaben","description":"Die Aufgabenverwaltung ist das zentrale Element von Planora. Hier erstellen, organisieren und verfolgen Sie alle anfallenden T\xe4tigkeiten.","sidebar":"tutorialSidebar"},"planora/dashboard":{"id":"planora/dashboard","title":"Dashboard","description":"Das Dashboard ist die Startseite nach der Anmeldung. Es bietet eine schnelle \xdcbersicht \xfcber den aktuellen Arbeitstag, offene Aufgaben und anstehende Termine.","sidebar":"tutorialSidebar"},"planora/einstellungen":{"id":"planora/einstellungen","title":"Einstellungen","description":"Unter Einstellungen (unten in der Seitenleiste) passen Sie Planora an Ihre pers\xf6nlichen Bed\xfcrfnisse an und verwalten Zugangsdaten sowie Module. Die Abschnitte stehen links bzw. auf schmalen Bildschirmen als Leiste oben; einzelne erscheinen nur mit dem passenden Modul oder mit Administratorrechten.","sidebar":"tutorialSidebar"},"planora/faq":{"id":"planora/faq","title":"FAQ \u2013 H\xe4ufige Fragen","description":"Hier finden Sie Antworten auf die h\xe4ufigsten Fragen zu Planora.","sidebar":"tutorialSidebar"},"planora/it/datenschutz":{"id":"planora/it/datenschutz","title":"Datenschutz","description":"Der Bereich Datenschutz f\xfchrt das Verzeichnis der Verarbeitungst\xe4tigkeiten nach Art. 30 DSGVO, die technischen und organisatorischen Ma\xdfnahmen (TOM) nach Art. 32 DSGVO und die Dokumentation von Datenschutzverletzungen nach Art. 33/34 DSGVO. Er ist eng mit der IT-Dokumentation verkn\xfcpft: Verfahren h\xe4ngen an Diensten und Vertr\xe4gen, Datenpannen an St\xf6rungen im Logbuch.","sidebar":"tutorialSidebar"},"planora/it/dienste":{"id":"planora/it/dienste","title":"Dienste & Vertr\xe4ge","description":"Ein Dienst ist das, was Nutzerinnen und Nutzer tats\xe4chlich verwenden \u2013 etwa Scholar, IServ, der RADIUS-Server oder das WLAN. Er l\xe4uft auf einem Ger\xe4t oder einem Verbund und h\xe4ngt oft von weiteren Diensten, Zertifikaten und Vertr\xe4gen ab. Diese Seite beschreibt Dienste, Zertifikate & Domains, Vertr\xe4ge & Lizenzen sowie das Notfallhandbuch.","sidebar":"tutorialSidebar"},"planora/it/geraete":{"id":"planora/it/geraete","title":"Ger\xe4te","description":"Ger\xe4te sind das Herzst\xfcck der IT-Dokumentation: Server, virtuelle Maschinen, Netzwerktechnik, Drucker, Tablets und Arbeitspl\xe4tze. Je nach Art pflegen Sie sie in einer von drei Listen \u2013 alle zeigen auf dieselben Ger\xe4te.","sidebar":"tutorialSidebar"},"planora/it/netz":{"id":"planora/it/netz","title":"Netz & IP-Adressen","description":"Unter Netz & IPs verwaltet die IT-Dokumentation das IP-Adressmanagement (IPAM): Netze, Vergabebereiche, einzelne Adressen und VLANs. Adressen werden nach ihrem Zahlenwert sortiert \u2013 .9 steht also vor .10.","sidebar":"tutorialSidebar"},"planora/it/uebersicht":{"id":"planora/it/uebersicht","title":"IT-Dokumentation \u2013 \xdcbersicht","description":"Die IT-Dokumentation f\xfchrt die gesamte IT-Infrastruktur der Schule an einer Stelle Alle, deren Rolle das Modul freigibt, sehen und pflegen dieselben Daten.","sidebar":"tutorialSidebar"},"planora/it/wartung":{"id":"planora/it/wartung","title":"Wartung & Logbuch","description":"Die Wartung h\xe4lt fest, was turnusm\xe4\xdfig anf\xe4llt \u2013 Restore-Test, USV-Akkutausch, Firewall-Review, DGUV-V3-Pr\xfcfung, Inventur oder die Versionspr\xfcfung eines Servers. Das Logbuch dokumentiert, was tats\xe4chlich an einem System gemacht wurde.","sidebar":"tutorialSidebar"},"planora/it/zugaenge":{"id":"planora/it/zugaenge","title":"Zug\xe4nge & Gastzug\xe4nge","description":"Zwei Bereiche der IT-Dokumentation drehen sich um Menschen von au\xdfen: Zug\xe4nge halten fest, welche Konten Externe in den Systemen der Schule bekommen haben. Gastzug\xe4nge erlauben dem Schultr\xe4ger oder Dienstleistern einen zeitlich begrenzten Blick in die IT-Dokumentation selbst.","sidebar":"tutorialSidebar"},"planora/kalender":{"id":"planora/kalender","title":"Kalender","description":"Der Kalender erm\xf6glicht die Planung von Terminen und Ereignissen in einem oder mehreren eigenen Kalendern. Aufgaben mit F\xe4lligkeitsdatum und Notiz-ToDos k\xf6nnen zus\xe4tzlich eingeblendet werden.","sidebar":"tutorialSidebar"},"planora/notizen":{"id":"planora/notizen","title":"Notizzettel","description":"Die Notizzettel ersetzen den Papierstapel neben dem Telefon. Sie halten kurze Vermerke, Telefonnotizen und kleine ToDos fest, die keine vollst\xe4ndige Aufgabe rechtfertigen. Die Zettel h\xe4ngen wie Post-its auf einem Board.","sidebar":"tutorialSidebar"},"planora/projekte":{"id":"planora/projekte","title":"Projekte","description":"Projekte helfen dabei, Aufgaben thematisch zu b\xfcndeln und den \xdcberblick \xfcber gr\xf6\xdfere Vorhaben zu behalten. Sie finden sie unter Board \u2192 \ud83d\udcc1 Projekte.","sidebar":"tutorialSidebar"},"planora/schilder":{"id":"planora/schilder","title":"Schilder","description":"Die Schilder-Funktion erm\xf6glicht das Erstellen digitaler Statusschilder \u2013 etwa f\xfcr ein T\xfcrschild-Display vor dem B\xfcro. Sie finden sie \xfcber T\xfcrschild in der Seitenleiste.","sidebar":"tutorialSidebar"},"planora/server":{"id":"planora/server","title":"Serververwaltung","description":"Das fr\xfchere Server-Modul gibt es nicht mehr. Es wurde durch die IT-Dokumentation ersetzt, die Standorte, Ger\xe4te, Netze, Dienste, Vertr\xe4ge, Wartung und Logbuch organisationsweit an einer Stelle f\xfchrt.","sidebar":"tutorialSidebar"},"planora/start":{"id":"planora/start","title":"Planora \u2013 \xdcbersicht","description":"Planora ist eine moderne Arbeitsmanagement-Plattform f\xfcr Teams und Organisationen. Sie vereint Aufgabenverwaltung, Projektverfolgung, Zeiterfassung, Teamkoordination und die IT-Dokumentation der Schule in einer einzigen Anwendung.","sidebar":"tutorialSidebar"},"planora/statistiken":{"id":"planora/statistiken","title":"Statistiken","description":"Die Statistikseite wertet aus, was Sie in Planora erfasst haben: erledigte Aufgaben, Verteilung auf Projekte und Priorit\xe4ten sowie die gebuchten Arbeitszeiten. Sie beantwortet vor allem die Frage, wo die Zeit tats\xe4chlich hingeht.","sidebar":"tutorialSidebar"},"planora/terminbuchung":{"id":"planora/terminbuchung","title":"Kalenderfreigabe & Terminbuchung","description":"Kalender in Planora lassen sich nach au\xdfen \xf6ffnen: als reine Leseansicht, als Buchungsseite f\xfcr freie Zeitslots oder als Formular f\xfcr Terminvorschl\xe4ge. Externe Personen ben\xf6tigen daf\xfcr kein Planora-Konto \u2013 der Zugriff l\xe4uft ausschlie\xdflich \xfcber einen Link.","sidebar":"tutorialSidebar"},"planora/zeiterfassung":{"id":"planora/zeiterfassung","title":"Zeiterfassung","description":"Die Zeiterfassung erm\xf6glicht eine detaillierte Protokollierung von Arbeitszeiten, Urlaub, Krankheit und \xdcberstunden. Grundlage ist ein pers\xf6nliches Arbeitszeitmodell, das sich am TV-L bzw. TV-H und am Arbeitszeitgesetz orientiert.","sidebar":"tutorialSidebar"},"scholar/administration":{"id":"scholar/administration","title":"Administration","description":"Der Administrationsbereich (Men\xfc Admin) ist Benutzerinnen und Benutzern mit der Rolle Admin oder Schulleitung vorbehalten. Wer nur das Export-Recht besitzt, sieht ausschlie\xdflich den Bereich Export. Hier werden alle systemweiten Einstellungen verwaltet.","sidebar":"tutorialSidebar"},"scholar/ags":{"id":"scholar/ags","title":"Arbeitsgemeinschaften (AGs)","description":"Das AG-Modul verwaltet alle schulischen Arbeitsgemeinschaften und die Zuweisung von Sch\xfclerinnen und Sch\xfclern. Sie erreichen es \xfcber das Men\xfc AG Modul mit den Punkten \xdcbersicht, Zuweisung / Entfernen und Statistik.","sidebar":"tutorialSidebar"},"scholar/ausgabe":{"id":"scholar/ausgabe","title":"Lernmittelausgabe (Sch\xfclerhilfe)","description":"Die Sch\xfclerhilfe ist die Arbeitsoberfl\xe4che f\xfcr die Buchausgabe. Sie b\xfcndelt alles, was an der Ausgabetheke gebraucht wird: Sch\xfclersuche, die passende B\xfccherliste, den Kontostand und die R\xfcckmeldung, welche Lernmittel noch fehlen.","sidebar":"tutorialSidebar"},"scholar/bibliothek":{"id":"scholar/bibliothek","title":"Bibliothek","description":"Das Bibliotheksmodul verwaltet den gesamten Medienbestand der Schulbibliothek \u2013 von der Katalogisierung bis zur Ausleihverwaltung.","sidebar":"tutorialSidebar"},"scholar/checklisten":{"id":"scholar/checklisten","title":"Checklisten","description":"Mit Checklisten werden wiederkehrende Abl\xe4ufe strukturiert abgearbeitet \u2013 z. B. Aufgaben zum Schuljahresbeginn, Klassenleitungs-Pflichten oder \xdcbergaben. Checklisten werden zentral erstellt, an Personen oder Rollen zugewiesen und in ihrem Bearbeitungsstand nachverfolgt.","sidebar":"tutorialSidebar"},"scholar/dashboard":{"id":"scholar/dashboard","title":"Dashboard","description":"Das Dashboard ist die Startseite nach der Anmeldung. Es bietet eine schnelle \xdcbersicht \xfcber aktuelle Vorg\xe4nge und wichtige Informationen.","sidebar":"tutorialSidebar"},"scholar/eltern":{"id":"scholar/eltern","title":"Elternverwaltung","description":"Die Elternverwaltung erm\xf6glicht die Pflege aller Erziehungsberechtigten und deren Verkn\xfcpfung mit Sch\xfclerinnen und Sch\xfclern. Sie erreichen sie \xfcber das Men\xfc Erziehungsberechtigte.","sidebar":"tutorialSidebar"},"scholar/fachkonferenzen":{"id":"scholar/fachkonferenzen","title":"Fachkonferenzen (FKL-Verwaltung)","description":"Im Men\xfc FKL-Verwaltung finden Fachkonferenzleitungen alles, was sie f\xfcr ihr Fach ben\xf6tigen: die Lernmittelliste, die Fachschaft, die Vertreterinnen und Vertreter in der Fachkonferenz, die Einladungen zur Konferenz und die Notengewichtung.","sidebar":"tutorialSidebar"},"scholar/fallmanagement":{"id":"scholar/fallmanagement","title":"Fallmanagement & Kiosk","description":"Das Fallmanagement-Modul erm\xf6glicht die digitale Abwicklung von Formularen und Vorg\xe4ngen \u2013 sowohl durch Mitarbeitende als auch \xfcber einen Kiosk-Touchscreen und \xfcber Freigabe-Links, die Eltern per E-Mail erhalten. Sie erreichen die Fallverwaltung \xfcber das Men\xfc Org oder die Kachel Case Management in der Administration.","sidebar":"tutorialSidebar"},"scholar/faq":{"id":"scholar/faq","title":"FAQ \u2013 H\xe4ufige Fragen","description":"Hier finden Sie Antworten auf die h\xe4ufigsten Fragen zu Scholar.","sidebar":"tutorialSidebar"},"scholar/finanzen":{"id":"scholar/finanzen","title":"Finanzen & Zahlungen","description":"Scholar bildet den Zahlungsverkehr rund um Lernmittel, Geb\xfchren und Barkassen ab. Zahlungseing\xe4nge werden aus dem Bankkonto importiert, automatisch Sch\xfclerinnen und Sch\xfclern zugeordnet und mit deren Lernmittelkonto verrechnet.","sidebar":"tutorialSidebar"},"scholar/geraete":{"id":"scholar/geraete","title":"Ger\xe4teverwaltung","description":"Das Ger\xe4temodul verwaltet das gesamte Schulinventar an technischen Ger\xe4ten \u2013 von der Ausleihe \xfcber Wartung und Lager bis zur Inventur. Die Funktionen verteilen sich auf das Men\xfc Module (Ger\xe4te, ausgeliehene Ger\xe4te, Leihverlauf), die Navigationsgruppe Lagerverwaltung (Wartungs\xfcbersicht, Lagerorte, Lager\xfcbersicht / Scanner) und das Men\xfc Reservierungen \u2192 Ger\xe4te.","sidebar":"tutorialSidebar"},"scholar/klassengeld":{"id":"scholar/klassengeld","title":"Klassengeld","description":"Das Klassengeld-Modul verwaltet Geldsammlungen f\xfcr Klassen- und AG-Vorhaben \u2013 etwa Fahrten, Ausfl\xfcge oder Materialbeitr\xe4ge. Forderungen, Zahlungseing\xe4nge, Auszahlungen und Klassenkassen werden zentral \xfcber das Schulkonto abgebildet.","sidebar":"tutorialSidebar"},"scholar/lernmittel":{"id":"scholar/lernmittel","title":"Lernmittel","description":"Das Lernmittelmodul verwaltet Schulb\xfccher, Arbeitshefte, digitale Lernmittel, Materialpreise und Bestellungen f\xfcr alle Sch\xfclerinnen und Sch\xfcler. Alle Funktionen liegen im Men\xfc Module \u2192 Schulbuch (LM); welche Eintr\xe4ge sichtbar sind, h\xe4ngt von den Lernmittel-Berechtigungen ab.","sidebar":"tutorialSidebar"},"scholar/listen":{"id":"scholar/listen","title":"Listen, Druck & \xdcbersichten","description":"Scholar erzeugt aus dem Datenbestand fertige Listen f\xfcr den Schulalltag \u2013 von der Klassenliste \xfcber Klassenfotos und Barcode-Etiketten bis zur Notfallcheckliste. Alle Ausgaben stehen als Bildschirmansicht und als PDF zur Verf\xfcgung.","sidebar":"tutorialSidebar"},"scholar/mitarbeiter":{"id":"scholar/mitarbeiter","title":"Mitarbeitende & On-/Offboarding","description":"Neben Sch\xfclerinnen und Sch\xfclern verwaltet Scholar auch die Konten der Mitarbeitenden. Der Onboarding-Bereich b\xfcndelt alle Zugangsdaten, die beim Dienstantritt vergeben werden, und dokumentiert deren Ausgabe.","sidebar":"tutorialSidebar"},"scholar/noten":{"id":"scholar/noten","title":"Noten & Zeugnisse","description":"Das Notenmodul erm\xf6glicht die vollst\xe4ndige Verwaltung von Noten, Beurteilungen und Zeugnissen. Sie erreichen es \xfcber das Men\xfc Notensystem:","sidebar":"tutorialSidebar"},"scholar/schliessacher":{"id":"scholar/schliessacher","title":"Schlie\xdff\xe4cher","description":"Das Schlie\xdffachmodul verwaltet alle Schlie\xdff\xe4cher der Schule \u2013 von der Standortverwaltung bis zur Zuweisung an Sch\xfclerinnen und Sch\xfcler.","sidebar":"tutorialSidebar"},"scholar/schueler":{"id":"scholar/schueler","title":"Sch\xfclerverwaltung","description":"Die Sch\xfclerverwaltung ist das Herzst\xfcck von Scholar. Hier werden alle sch\xfclerbezogenen Daten gepflegt und verwaltet.","sidebar":"tutorialSidebar"},"scholar/schulkueche":{"id":"scholar/schulkueche","title":"Schulk\xfcche","description":"Die Schulk\xfcche wird \xfcber Scholar reserviert. Jede Nutzung durchl\xe4uft Antrag, Genehmigung und R\xfcckgabepr\xfcfung \u2013 damit ist jederzeit nachvollziehbar, wer die K\xfcche in welchem Zustand \xfcbernommen und zur\xfcckgegeben hat.","sidebar":"tutorialSidebar"},"scholar/selbstservice":{"id":"scholar/selbstservice","title":"Selbstservice-Portale","description":"Scholar bietet verschiedene Selbstservice-Portale, \xfcber die Sch\xfclerinnen, Sch\xfcler und Mitarbeitende ihre Zug\xe4nge eigenst\xe4ndig einrichten oder zur\xfccksetzen k\xf6nnen. Diese Portale sind IP-gesichert und teilweise ohne Anmeldung zug\xe4nglich. Die Identifikation erfolgt in der Regel \xfcber den Barcode des Sch\xfclerausweises und das Geburtsdatum.","sidebar":"tutorialSidebar"},"scholar/start":{"id":"scholar/start","title":"Scholar \u2013 \xdcbersicht","description":"Scholar ist das zentrale Schulverwaltungssystem der Wilhelm-Raabe-Schule. Es deckt alle administrativen Bereiche des Schulbetriebs ab \u2013 von der Sch\xfcleranmeldung \xfcber Noten und Zeugnisse bis hin zur Ger\xe4te- und Bibliotheksverwaltung.","sidebar":"tutorialSidebar"},"scholar/wlan":{"id":"scholar/wlan","title":"WLAN-Verwaltung","description":"Das WLAN-Modul verwaltet den Internetzugang f\xfcr Sch\xfclerinnen, Sch\xfcler und Mitarbeitende \xfcber das RADIUS-System.","sidebar":"tutorialSidebar"},"systemanforderungen":{"id":"systemanforderungen","title":"Systemanforderungen","description":"Diese Seite fasst zusammen, was f\xfcr den Betrieb von Scholar (einschlie\xdflich Elternportal) und Planora ben\xf6tigt wird \u2013 am Arbeitsplatz, auf dem Server und bei der eingesetzten Peripherie.","sidebar":"tutorialSidebar"}}}}')}}]);